<template>
  <div class="ai-container">
    <div class="header-card">
      <div class="title-section">
        <div class="icon-wrapper">
          <el-icon><ChatDotRound /></el-icon>
        </div>
        <span class="page-title">AI 助手</span>
      </div>
      <div class="status-bar">
        <div class="status-indicator" :class="{ active: healthOk, connecting: !healthOk }">
          <span class="status-dot"></span>
          <span class="status-text">{{ healthOk ? '服务已连接' : '正在连接...' }}</span>
        </div>
        <el-button text type="danger" @click="clearHistory" class="clear-btn">
          <el-icon><Delete /></el-icon>
          清空记录
        </el-button>
      </div>
    </div>

    <div class="chat-card" ref="chatRef">
      <div v-if="messages.length === 0" class="welcome-state">
        <div class="welcome-icon">
          <el-icon size="48"><ChatDotSquare /></el-icon>
        </div>
        <h3 class="welcome-title">你好，我是实验室 AI 助手</h3>
        <p class="welcome-desc">我可以帮你处理以下事务</p>
        <div class="suggestion-chips">
          <span class="chip" @click="input = '我要请假'; send()">
            <span class="chip-icon">📅</span>
            请假申请
          </span>
          <span class="chip" @click="input = '查找无人机'; send()">
            <span class="chip-icon">🔍</span>
            设备搜索
          </span>
          <span class="chip" @click="input = '借用示波器'; send()">
            <span class="chip-icon">📦</span>
            设备借用
