      </div>

      <div v-for="(msg, idx) in messages" :key="idx" class="msg-wrapper" :class="msg.role">
        <div class="avatar">
          <el-avatar v-if="msg.role === 'ai'" :size="36" class="ai-avatar">AI</el-avatar>
          <el-avatar v-else :size="36" class="user-avatar">我</el-avatar>
        </div>
        
        <div class="msg-content-area">
          <div class="msg-name">{{ msg.role === 'ai' ? '实验室智能管家' : '我' }}</div>
          <div class="bubble" :class="{ 'user-bubble': msg.role === 'user' }">
            <div class="content">{{ msg.text }}</div>
            <div v-if="msg.actions && msg.actions.length" class="actions">
              <div v-for="(a, aidx) in msg.actions" :key="a.borrow_record_id || a.approval_id || aidx">
                <!-- 预填单流：支持直接的 prefill 动作，或兼容旧的 borrow/leave_approval 类型 -->
                <template v-if="a.type==='lowcode_prefill' || a.type==='borrow' || a.type==='leave_approval'">
                  <div class="action-card success-card flex-between">
                    <div class="action-info">
                      <el-icon><EditPen /></el-icon>
                      <span>已为您准备好{{ a.app_code==='borrow'||a.type==='borrow'?'借用':'请假' }}申请表单</span>
                    </div>
                    <el-button size="small" type="primary" @click="openPrefillForm({
                      app_code: a.app_code || (a.type==='borrow'?'borrow':'leave'),
                      params: a.params || (a.type==='borrow'?{equipment_name: a.search_keyword}:{leave_type: a.leave_type, leave_reason: a.leave_reason})
                    })">打开并填写</el-button>
                  </div>
                </template>

                <!-- 文档预览 -->
                <template v-else-if="a.type==='document' && !a.error">
                  <div class="action-card success-card flex-between">
                    <div class="action-info">
                      <el-icon><Check /></el-icon>
                      <span>文档已上传：{{ a.title || ('文档ID ' + a.document_id) }}</span>
                    </div>
                    <el-button size="small" type="primary" plain @click="openDocument(a)">打开</el-button>
                  </div>
                </template>

                <!-- 错误提示 -->
                <template v-else-if="a.error">
                  <div class="action-card error-card">
                    <el-icon><Close /></el-icon>
                    <span>操作未完成：{{ a.error }}</span>
                  </div>
                </template>

                <!-- 旧版交互式卡片（保留作为兼容） -->
                <template v-else-if="a.type==='leave_prompt'">
                  <div class="leave-prompt-card">
                    <div class="card-header">
                      <el-icon><EditPen /></el-icon>
                      请假信息确认
                    </div>
                    <div v-if="a.leave_types && a.leave_types.length" class="leave-row">
                      <span class="leave-label">假别</span>
                      <div class="leave-buttons">
                        <el-button
                          v-for="t in a.leave_types"
                          :key="t.value"
                          size="small"
                          :type="leaveDraft.leave_type === t.value ? 'primary' : 'default'"
                          :plain="leaveDraft.leave_type !== t.value"
                          @click="selectLeaveType(t.value)"
                        >{{ t.label }}</el-button>
                      </div>
                    </div>
                    <div v-if="a.teachers && a.teachers.length" class="leave-row">
                      <span class="leave-label">审批人</span>
                      <div class="leave-buttons">
                        <el-button
                          v-for="u in a.teachers"
                          :key="u.id"
                          size="small"
                          :type="leaveDraft.leave_approver_id === u.id ? 'primary' : 'default'"
                          :plain="leaveDraft.leave_approver_id !== u.id"
                          @click="selectLeaveApprover(u)"
                        >{{ u.name }}<span v-if="u.role">（{{ u.role }}）</span></el-button>
                      </div>
                    </div>
                  </div>
                </template>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div v-if="loading" class="msg-wrapper ai">
        <div class="avatar">
          <el-avatar :size="36" class="ai-avatar">AI</el-avatar>
        </div>
        <div class="msg-content-area">
          <div class="msg-name">实验室智能管家</div>
          <div class="bubble typing-bubble">
            <div class="typing-indicator">
              <span></span><span></span><span></span>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div class="input-card">
      <div class="input-bar">
        <el-input 
          v-model="input" 
          placeholder="输入您的问题，例如：我想借用一台无人机..." 
          @keyup.enter="send" 
          clearable
          size="large"
          class="chat-input"
        >
          <template #prefix>
            <el-icon><EditPen /></el-icon>
          </template>
        </el-input>
        <el-button type="primary" size="large" @click="send" :loading="loading" class="send-btn">
          <el-icon><Promotion /></el-icon>
          发送
        </el-button>
        <el-button
          size="large"
          :type="isListening ? 'danger' : 'default'"
          class="voice-btn"
          @click="toggleListening"
        >
          {{ isListening ? '停止识别' : '语音输入' }}
        </el-button>
      </div>
      <div class="input-tools">
        <div class="input-hint">
          按 Enter 键发送消息
          <span v-if="voiceHint" class="voice-hint">{{ voiceHint }}</span>
        </div>
        <el-switch
          v-model="autoSpeak"
          inline-prompt
          active-text="自动播报"
          inactive-text="静音"
          class="tts-switch"
        />
      </div>
    </div>

    <el-dialog 
      v-model="prefillDialogVisible" 
      :title="'确认' + (prefillAction?.app_code || '') + '申请'" 
      width="600px"
      destroy-on-close
      class="feishu-dialog"
    >
      <DynamicForm 
        v-if="prefillDialogVisible && prefillAction"
        :appCode="prefillAction.app_code"
        :initialData="prefillAction.params"
        @success="handlePrefillSuccess"
        @cancel="prefillDialogVisible = false"
      />
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, onMounted, nextTick, watch, onUnmounted } from 'vue'
import { ChatDotRound, Delete, Promotion, Check, Close, InfoFilled, CircleCheckFilled, EditPen, ChatDotSquare } from '@element-plus/icons-vue'
import api from '@/api'
import { ElMessage } from 'element-plus'
import DynamicForm from '@/components/DynamicForm.vue'

const input = ref('')
const messages = ref([])
const loading = ref(false)
const healthOk = ref(false)
const chatRef = ref(null)
const sessionId = ref('default')
const leaveDraft = ref({ leave_type: '', leave_reason: '', leave_approver_id: null })
const prefillDialogVisible = ref(false)
const prefillAction = ref(null)
const isListening = ref(false)
const autoSpeak = ref(true)
const voiceHint = ref('')
let healthTimer = null
let recognition = null

const openPrefillForm = (a) => {
  prefillAction.value = a
  prefillDialogVisible.value = true
}

const handlePrefillSuccess = () => {
  prefillDialogVisible.value = false
  ElMessage.success('申请提交成功')
}

const scrollBottom = () => {
  nextTick(() => {
    if (chatRef.value) chatRef.value.scrollTop = chatRef.value.scrollHeight
  })
}

const getUserId = () => {
  try {
    const u = JSON.parse(localStorage.getItem('user') || '{}')
    // Go 后端 UserDTO 返回的字段是: id, user_id (都是小写)
    return u.id || u.User_id || u.Id || null
  } catch {
    return null
  }
}

const getStorageKey = () => {
  const uid = getUserId()
  return `ai_chat_${uid || 'guest'}_${sessionId.value}`
}

const getLeaveKey = () => {
  const uid = getUserId()
  return `ai_leave_${uid || 'guest'}_${sessionId.value}`
}

const loadLeaveDraft = () => {
  try {
    const s = localStorage.getItem(getLeaveKey())
    if (s) {
      const obj = JSON.parse(s)
      if (obj && typeof obj === 'object') leaveDraft.value = { ...leaveDraft.value, ...obj }
    }
  } catch {}
}

const saveLeaveDraft = () => {
  try {
    localStorage.setItem(getLeaveKey(), JSON.stringify(leaveDraft.value))
  } catch {}
}

const loadMessages = () => {
  try {
    const s = localStorage.getItem(getStorageKey())
    if (s) {
      const arr = JSON.parse(s)
      if (Array.isArray(arr)) messages.value = arr
    }
  } catch {}
}

const saveMessages = () => {
  try {
    localStorage.setItem(getStorageKey(), JSON.stringify(messages.value))
  } catch {}
}

const clearHistory = () => {
  const uid = getUserId()
  messages.value = []
  try {
    localStorage.removeItem(getStorageKey())
  } catch {}
  if (uid) {
    api.aiClear(uid, sessionId.value).catch(() => {})
  }
}

const clearLeaveDraft = () => {
  leaveDraft.value = { leave_type: '', leave_reason: '', leave_approver_id: null }
  try {
    localStorage.removeItem(getLeaveKey())
  } catch {}
}

const selectLeaveApprover = (u) => {
  leaveDraft.value.leave_approver_id = u.id
  saveLeaveDraft()
}

const selectLeaveType = (v) => {
  leaveDraft.value.leave_type = v
  saveLeaveDraft()
}

const extractReasonFromText = (text) => {
  if (!text) return ''
  if (text.includes('因为')) return text.split('因为', 2)[1].trim()
  if (text.includes('原因')) return text.split('原因', 2)[1].trim()
  return ''
}

const sendChat = async (text) => {
  const uid = getUserId()
  console.log('[AI] Sending chat - uid:', uid, 'text:', text)
  const extra = {}
  if (leaveDraft.value.leave_type) extra.leave_type = leaveDraft.value.leave_type
  if (leaveDraft.value.leave_approver_id) extra.leave_approver_id = leaveDraft.value.leave_approver_id
  if (leaveDraft.value.leave_reason) extra.leave_reason = leaveDraft.value.leave_reason
  if (extra.leave_type || extra.leave_approver_id || extra.leave_reason) extra.leave_intent = true
  try {
    const r = await api.aiChat(text, uid, sessionId.value, extra)
    console.log('[AI] Response:', r.data)
    return r
  } catch (e) {
    console.error('[AI] Error:', e.response?.data || e.message)
    throw e
  }
}

const openDocument = (a) => {
  const base = typeof api.getBackendBaseURL === 'function' ? api.getBackendBaseURL() : 'http://localhost:8000'
  const url = a?.file
  if (!url) {
    ElMessage.error('该文档没有可打开的文件链接')
    return
  }
  const full = String(url).startsWith('http') ? url : `${base}${String(url).startsWith('/') ? '' : '/'}${url}`
  window.open(full, '_blank')
}

const checkHealth = async () => {
  try {
    const r = await api.aiHealth()
    // OpenClaw health 可能返回 {status: "ok"} 或其他格式
    healthOk.value = r && (r.status === 200 || r.data?.status === 'ok' || !r.data?.error)
  } catch (e) {
    console.warn('AI health check failed:', e)
    healthOk.value = false
  }
}

const startHealthCheck = () => {
  checkHealth()
  healthTimer = setInterval(checkHealth, 30000)
}

const loadServerHistory = async () => {
  const uid = getUserId()
  if (!uid) return
  try {
    const r = await api.aiHistory(uid, sessionId.value)
    const arr = r.data || []
    if (Array.isArray(arr) && arr.length > 0) {
      messages.value = arr.map(m => ({ role: m.role, text: m.text, actions: m.actions || [] }))
      saveMessages()
      scrollBottom()
    }
  } catch {}
}

const send = async () => {
  const text = (input.value || '').trim()
  if (!text) return

  const uid = getUserId()
  if (!uid) {
    ElMessage.error('请先登录后再使用AI助手')
    return
  }

  if (!leaveDraft.value.leave_reason) {
    const r = extractReasonFromText(text)
    if (r) {
      leaveDraft.value.leave_reason = r
      saveLeaveDraft()
    } else if (leaveDraft.value.leave_type && leaveDraft.value.leave_approver_id && !text.includes('请假')) {
      leaveDraft.value.leave_reason = text
      saveLeaveDraft()
    }
  }
  messages.value.push({ role: 'user', text })
  saveMessages()
  input.value = ''
  loading.value = true
  scrollBottom()
  try {
    const r = await sendChat(text)
    const data = r.data || {}
    const answerText = data.text || data.answer || '已处理'
    messages.value.push({ role: 'ai', text: answerText, actions: data.actions || [] })
    if (autoSpeak.value) {
      speakText(answerText)
    }
    const ok = (data.actions || []).some(a => a.type === 'leave_approval' && !a.error)
    if (ok) clearLeaveDraft()
    saveMessages()
  } catch (e) {
    console.error('AI chat error:', e)
    // 提供更详细的错误信息
    const errorMsg = e?.response?.data?.error || e?.message || '发送失败'
    ElMessage.error(`发送失败: ${errorMsg}`)
  } finally {
    loading.value = false
    scrollBottom()
  }
}

const getSpeechRecognition = () => {
  if (typeof window === 'undefined') return null
  return window.SpeechRecognition || window.webkitSpeechRecognition || null
}

const initSpeechRecognition = () => {
  const SR = getSpeechRecognition()
  if (!SR) {
    voiceHint.value = '当前浏览器不支持语音识别，建议使用 Chrome 或 Edge'
    return
  }
  recognition = new SR()
  recognition.lang = 'zh-CN'
  recognition.continuous = false
  recognition.interimResults = false
  recognition.maxAlternatives = 1

  recognition.onstart = () => {
    isListening.value = true
    voiceHint.value = '正在听，请开始说话...'
  }
  recognition.onresult = (event) => {
    const result = event.results?.[0]?.[0]?.transcript || ''
    if (result) {
      input.value = result.trim()
      voiceHint.value = `识别完成: ${input.value}`
    }
  }
  recognition.onerror = (event) => {
    isListening.value = false
    const code = event?.error || 'unknown'
    if (code === 'not-allowed') {
      voiceHint.value = '麦克风权限被拒绝，请在浏览器地址栏开启麦克风权限'
      return
    }
    if (code === 'no-speech') {
      voiceHint.value = '未识别到语音，请再试一次'
      return
    }
    voiceHint.value = `语音识别失败: ${code}`
  }
  recognition.onend = () => {
    isListening.value = false
    if (voiceHint.value === '正在听，请开始说话...') {
      voiceHint.value = '语音识别已结束'
    }
  }
}

const toggleListening = () => {
  if (!recognition) {
    initSpeechRecognition()
  }
  if (!recognition) return
  if (isListening.value) {
    recognition.stop()
    return
  }
  try {
    recognition.start()
  } catch {
    // Already started; ignore duplicate start calls.
  }
}

const speakText = (text) => {
  if (!text || typeof window === 'undefined' || !window.speechSynthesis) return
  const trimmed = String(text).trim()
  if (!trimmed) return
  window.speechSynthesis.cancel()
  const utterance = new SpeechSynthesisUtterance(trimmed)
  utterance.lang = 'zh-CN'
  utterance.rate = 1
  utterance.pitch = 1
  window.speechSynthesis.speak(utterance)
}

onMounted(() => {
  loadMessages()
  loadLeaveDraft()
  scrollBottom()
  startHealthCheck()
  loadServerHistory()
  initSpeechRecognition()
})

onUnmounted(() => {
  if (healthTimer) {
    clearInterval(healthTimer)
  }
  if (recognition && isListening.value) {
    recognition.stop()
  }
  if (typeof window !== 'undefined' && window.speechSynthesis) {
    window.speechSynthesis.cancel()
  }
})

watch(messages, () => {
  saveMessages()
}, { deep: true })

watch(leaveDraft, () => {
  saveLeaveDraft()
}, { deep: true })
</script>

